/**
 * `pasco export ai-policy --check --file <robots.txt>` — verify a committed file
 * against the registry (#477).
 *
 * The contracts that matter here:
 *   1. the file the engine EMITS passes with zero findings — the canonical
 *      fixture is generated by `renderRobots`, so it cannot drift from the
 *      renderer;
 *   2. a file with the two lists swapped FAILS, one finding per crawler: that is
 *      the case a structural gate passes green, and the whole reason this
 *      command exists;
 *   3. each detection has its own finding kind — absent, duplicated, in the
 *      group that states the opposite rule, a wildcard group, a rule no group
 *      owns — never a generic "invalid robots.txt";
 *   4. parsing is RFC 9309 §2.2: a `User-agent` line after a group's rules starts
 *      a new group, before them it joins the group; `#` starts a comment; an
 *      unknown record (`Sitemap`) does not terminate a group; a rule before the
 *      first `User-agent` belongs to no group;
 *   5. no workspace, no clock: the same text yields the same findings, and
 *      `--check` without `--file` keeps its previous contract.
 */

import { spawnSync } from "node:child_process";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { AI_CRAWLERS } from "@profile-as-code/core";
import { afterAll, describe, expect, it } from "vitest";
import { renderRobots, runAiPolicyFileCheck } from "../src/commands/export.js";
import { parseRobots, verifyRobotsFile } from "../src/commands/robots.js";
import { setJsonMode } from "../src/output.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const CLI = join(__dirname, "..", "dist", "index.js");

const retrieval = AI_CRAWLERS.filter((row) => row.family === "retrieval");
const training = AI_CRAWLERS.filter((row) => row.family === "training");

const tempDirs: string[] = [];
function tempDir(): string {
  const dir = mkdtempSync(join(tmpdir(), "pasco-robots-"));
  tempDirs.push(dir);
  return dir;
}
afterAll(() => {
  for (const dir of tempDirs) rmSync(dir, { recursive: true, force: true });
});

/** The engine's own artifact — the canonical fixture. */
const canonical = renderRobots(AI_CRAWLERS);

/** Build a robots.txt from the pieces a test cares about. */
function robotsText(groups: { agents: string[]; rule: "Allow" | "Disallow" }[]): string {
  return `${groups
    .map((group) =>
      [...group.agents.map((agent) => `User-agent: ${agent}`), `${group.rule}: /`, ""].join("\n"),
    )
    .join("\n")}\n`;
}

/** The posture the registry declares, spelled out. */
const correct = robotsText([
  { agents: retrieval.map((row) => row.ua), rule: "Allow" },
  { agents: training.map((row) => row.ua), rule: "Disallow" },
]);

/** The inversion: the two lists swapped, so the posture is exactly reversed. */
const swapped = robotsText([
  { agents: training.map((row) => row.ua), rule: "Allow" },
  { agents: retrieval.map((row) => row.ua), rule: "Disallow" },
]);

/** Capture stdout for a command run (JSON envelopes and report lines both go there). */
function capture<T>(run: () => T): { code: T; out: string } {
  const original = process.stdout.write.bind(process.stdout);
  let out = "";
  process.stdout.write = ((chunk: string) => {
    out += chunk;
    return true;
  }) as typeof process.stdout.write;
  try {
    return { code: run(), out };
  } finally {
    process.stdout.write = original;
    setJsonMode(false);
  }
}

describe("parseRobots — RFC 9309 §2.2 groups", () => {
  it("parses the emitted artifact into its two groups", () => {
    const parsed = parseRobots(canonical);
    expect(parsed.groups).toHaveLength(2);
    expect(parsed.groups[0]?.agents).toEqual(retrieval.map((row) => row.ua));
    expect(parsed.groups[1]?.agents).toEqual(training.map((row) => row.ua));
    expect(parsed.groups[0]?.rules).toEqual([
      { line: expect.any(Number), key: "allow", path: "/" },
    ]);
    expect(parsed.groups[1]?.rules).toEqual([
      { line: expect.any(Number), key: "disallow", path: "/" },
    ]);
    expect(parsed.orphanRules).toEqual([]);
  });

  it("joins consecutive User-agent lines and starts a new group after rules", () => {
    const parsed = parseRobots(
      [
        "User-agent: barbot",
        "User-agent: bazbot",
        "Disallow: /example/page.html",
        "User-agent: quxbot",
        "",
      ].join("\n"),
    );
    expect(parsed.groups.map((group) => group.agents)).toEqual([["barbot", "bazbot"], ["quxbot"]]);
    expect(parsed.groups[1]?.rules).toEqual([]);
  });

  it("ignores comments and other records without terminating the group", () => {
    const parsed = parseRobots(
      [
        "# a comment",
        "User-agent: ExampleBot  # trailing comment",
        "Disallow: /private",
        "Sitemap: https://example.com/sitemap.xml",
        "Allow: / # inline comment",
        "",
      ].join("\n"),
    );
    expect(parsed.groups).toHaveLength(1);
    expect(parsed.groups[0]?.rules).toEqual([
      { line: 3, key: "disallow", path: "/private" },
      { line: 5, key: "allow", path: "/" },
    ]);
  });

  it("reports a rule that precedes the first User-agent as belonging to no group", () => {
    const parsed = parseRobots(["Disallow: /", "User-agent: ExampleBot", "Allow: /"].join("\n"));
    expect(parsed.orphanRules).toEqual([{ line: 1, key: "disallow", path: "/" }]);
    expect(parsed.groups[0]?.agents).toEqual(["ExampleBot"]);
    expect(parsed.groups[0]?.rules).toEqual([{ line: 3, key: "allow", path: "/" }]);
  });

  it("is deterministic: the same text yields the same structure", () => {
    expect(parseRobots(canonical)).toEqual(parseRobots(canonical));
  });
});

describe("verifyRobotsFile — the agent↔group map", () => {
  it("accepts the file the engine emits (zero findings)", () => {
    expect(verifyRobotsFile(parseRobots(canonical), AI_CRAWLERS)).toEqual([]);
    expect(verifyRobotsFile(parseRobots(correct), AI_CRAWLERS)).toEqual([]);
  });

  it("FAILS the two lists swapped: one wrong-group finding per crawler", () => {
    const findings = verifyRobotsFile(parseRobots(swapped), AI_CRAWLERS);
    expect(findings).toHaveLength(AI_CRAWLERS.length);
    expect(findings.every((finding) => finding.kind === "wrong-group")).toBe(true);
    expect(findings.map((finding) => finding.entry)).toEqual(AI_CRAWLERS.map((row) => row.slug));
    // The posture is reversed for every crawler, so none is merely missing.
    expect(findings.some((finding) => finding.kind === "missing")).toBe(false);
    const googlebot = findings.find((finding) => finding.entry === "googlebot");
    expect(googlebot?.detail).toContain('"Googlebot" is in the retrieval role');
    expect(googlebot?.detail).toContain("Disallow: /");
    expect(googlebot?.detail).toContain("expected `Allow: /`");
  });

  it("names a crawler absent from BOTH groups", () => {
    const text = canonical.replace(/\n?User-agent: GPTBot\n/u, "\n");
    const findings = verifyRobotsFile(parseRobots(text), AI_CRAWLERS);
    expect(findings.map((finding) => `${finding.kind}:${finding.entry}`)).toEqual([
      "missing:gptbot",
    ]);
    expect(findings[0]?.detail).toContain("ai-training");
  });

  it("names a crawler that appears in two groups (RFC merges them)", () => {
    const text = correct.replace("User-agent: GPTBot", "User-agent: GPTBot\nUser-agent: Googlebot");
    const findings = verifyRobotsFile(parseRobots(text), AI_CRAWLERS);
    expect(findings.map((finding) => `${finding.kind}:${finding.entry}`)).toEqual([
      "duplicate:googlebot",
    ]);
    expect(findings[0]?.detail).toContain("merges them");
  });

  it("names a `User-agent: *` group — the policy is an explicit list", () => {
    const text = `User-agent: *\nDisallow: /\n\n${correct}`;
    const findings = verifyRobotsFile(parseRobots(text), AI_CRAWLERS);
    expect(findings.map((finding) => finding.kind)).toEqual(["wildcard"]);
    expect(findings[0]?.entry).toBe("*");
  });

  it("fails `Allow: /` under the training crawlers and `Disallow: /` under retrieval", () => {
    const allowUnderTraining = correct.replaceAll("Disallow: /", "Allow: /");
    const trainingFindings = verifyRobotsFile(parseRobots(allowUnderTraining), AI_CRAWLERS);
    expect(trainingFindings.map((finding) => finding.entry)).toEqual(
      training.map((row) => row.slug),
    );

    const disallowUnderRetrieval = correct.replaceAll("Allow: /", "Disallow: /");
    const retrievalFindings = verifyRobotsFile(parseRobots(disallowUnderRetrieval), AI_CRAWLERS);
    expect(retrievalFindings.map((finding) => finding.entry)).toEqual(
      retrieval.map((row) => row.slug),
    );
  });

  it("names a `Disallow: /` whose group lost its User-agent (orphan rule)", () => {
    const text = "Disallow: /\n\n".concat(correct);
    const findings = verifyRobotsFile(parseRobots(text), AI_CRAWLERS);
    expect(findings.some((finding) => finding.kind === "orphan-rule")).toBe(true);
    const orphan = findings.find((finding) => finding.kind === "orphan-rule");
    expect(orphan?.detail).toContain("crawlers ignore it");
    expect(orphan?.detail).toContain("RFC 9309 §2.2.2");
  });

  it("fails an empty file: every registry crawler is missing", () => {
    const findings = verifyRobotsFile(parseRobots(""), AI_CRAWLERS);
    expect(findings).toHaveLength(AI_CRAWLERS.length);
    expect(findings.every((finding) => finding.kind === "missing")).toBe(true);
  });
});

describe("CLI surface — --check --file", () => {
  function run(args: string[], cwd?: string) {
    const env = { ...process.env };
    delete env.PROFILE_DATA_PATH;
    const res = spawnSync(process.execPath, [CLI, ...args], {
      encoding: "utf8",
      cwd,
      timeout: 15_000,
      env,
    });
    if (res.error !== undefined) throw res.error;
    return { code: res.status ?? -1, stdout: res.stdout ?? "", stderr: res.stderr ?? "" };
  }

  function fileWith(text: string): string {
    const dir = tempDir();
    const path = join(dir, "robots.txt");
    writeFileSync(path, text);
    return path;
  }

  it("passes the canonical file with no workspace and no clock", () => {
    const dir = tempDir();
    const path = join(dir, "robots.txt");
    writeFileSync(path, canonical);
    const res = run(["export", "ai-policy", "--check", "--file", path], dir);
    expect(res.code).toBe(0);
    expect(res.stdout).toContain("the agent↔group map matches the registry");
  });

  it("fails the swapped file and names the finding, not a generic refusal", () => {
    const path = fileWith(swapped);
    const res = run(["export", "ai-policy", "--check", "--file", path]);
    expect(res.code).toBe(1);
    expect(res.stdout).toContain("wrong-group · googlebot");
    expect(res.stdout).toContain("finding(s) — the file does not express the registry's posture");
    expect(res.stdout).not.toContain("invalid robots.txt");
  });

  it("is deterministic: two runs produce byte-identical stdout", () => {
    const path = fileWith(swapped);
    const first = run(["export", "ai-policy", "--check", "--file", path]);
    const second = run(["export", "ai-policy", "--check", "--file", path]);
    expect(first.stdout).toBe(second.stdout);
    expect(first.code).toBe(second.code);
  });

  it("--json carries the findings and the parsed map", () => {
    const path = fileWith(swapped);
    const res = run(["export", "ai-policy", "--check", "--file", path, "--json"]);
    const envelope = JSON.parse(res.stdout) as {
      command: string;
      ok: boolean;
      exitCode: number;
      data: {
        schemaVersion: string;
        file: string;
        policy: { version: number; asOf: string };
        groups: { line: number; agents: string[]; rules: unknown[] }[];
        findings: { kind: string; entry: string }[];
      };
    };
    expect(res.code).toBe(1);
    expect(envelope.command).toBe("export ai-policy");
    expect(envelope.ok).toBe(false);
    expect(envelope.data.schemaVersion).toBe("1");
    expect(envelope.data.file).toBe(path);
    expect(envelope.data.groups).toHaveLength(2);
    expect(envelope.data.findings).toHaveLength(AI_CRAWLERS.length);
    // No clock in the payload: a consumer's gate cannot depend on the day.
    expect(Object.keys(envelope.data)).not.toContain("problems");
    expect(envelope.data.policy.asOf).toMatch(/^\d{4}-\d{2}-\d{2}$/);
  });

  it("reports an unreadable file as a check failure, not a crash", () => {
    const missing = join(tempDir(), "nope.txt");
    const res = run(["export", "ai-policy", "--check", "--file", missing]);
    expect(res.code).toBe(1);
    expect(res.stderr).toContain("cannot read");
  });

  it("usage: --file needs --check", () => {
    expect(run(["export", "ai-policy", "--file", "/tmp/robots.txt"]).code).toBe(2);
    expect(run(["export", "ai-policy", "--out", "/tmp/x", "--file", "/tmp/r.txt"]).code).toBe(2);
    expect(run(["export", "ai-policy", "--check", "--force", "--file", "/tmp/x"]).code).toBe(2);
  });

  it("regression: --check without --file keeps its previous contract", () => {
    const res = run(["export", "ai-policy", "--check"], tempDir());
    expect(res.code).toBe(0);
    expect(res.stdout).toContain("sourced and inside the 180-day window");
  });

  it("`--help` documents the file mode", () => {
    const res = run(["export", "ai-policy", "--help"]);
    expect(res.code).toBe(0);
    expect(res.stdout).toContain("--file <robots.txt>");
    expect(res.stdout).toContain("agent↔group");
  });
});

describe("unit surface — the runner", () => {
  it("reads the file it is given and reports zero findings for the canonical text", () => {
    const path = join(tempDir(), "robots.txt");
    writeFileSync(path, canonical);
    const { code, out } = capture(() => runAiPolicyFileCheck({ file: path }));
    expect(code).toBe(0);
    expect(out).toContain("group(s)");
  });

  it("verifies a file that lives outside any workspace: the registry is the only input", () => {
    const path = join(tempDir(), "robots.txt");
    writeFileSync(path, canonical);
    // No `.pascorc`, no workspace argument, no PROFILE_DATA_PATH.
    expect(capture(() => runAiPolicyFileCheck({ file: path })).code).toBe(0);
  });
});
